from fractions import Fraction as F
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
names='TUVW'
cost=[F(1),F(1),F(17,10),F(21,10)]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(S):
 w=sum(rows[i][1] for i in S)
 return min((sum(F(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])],w) for i in S),'ABCD'[a]) for a in range(4))
def solve(S,avail,budget):
 best=stop(S)
 if budget:
  w=sum(rows[i][1] for i in S)
  for t in avail:
   val=cost[t]
   for b in (0,1):
    sub=[i for i in S if rows[i][2][t]==b]
    if sub: val+=F(sum(rows[i][1] for i in sub),w)*solve(sub,[j for j in avail if j!=t],budget-1)[0]
   best=min(best,(val,names[t]))
 return best
S=list(range(8)); w=sum(r[1] for r in rows)
print('STOP',stop(S))
for t in range(4):
 val=cost[t]; branch={}
 for b in (0,1):
  sub=[i for i in S if rows[i][2][t]==b]
  v,a=solve(sub,[j for j in range(4) if j!=t],1)
  val+=F(sum(rows[i][1] for i in sub),w)*v
  branch[b]=(a,str(v),float(v))
 print(names[t],str(val),float(val),branch)

